type official = {
  refers_to_secretary_of_treasury : bool;
}

type delegate = {
  authorized_officer_employee_or_agency : string;
  authorized_directly_or_by_redelegation : bool;
}

(* 7701(a)(12)(A)(i) *)
let delegate_of_secretary (official : official) : delegate =
  { authorized_officer_employee_or_agency = "treasury_officer_employee_or_agency";
    authorized_directly_or_by_redelegation = true }

(* 7701(a)(12)(A)(ii) - similarly construed for other officials *)
let delegate_of_other_official (official : official) : delegate =
  delegate_of_secretary official

let delegate_of (official : official) : delegate =
  if official.refers_to_secretary_of_treasury then delegate_of_secretary official
  else delegate_of_other_official official

type territory =
  | Guam
  | American_Samoa
  | Other_location

type tax_chapter =
  | Chapter_1
  | Chapter_2
  | Chapter_21
  | Other_chapter

type guam_samoa_context = {
  official : official;
  territory : territory;
  chapter : tax_chapter;
  authorized_by_secretary : bool;
  by_redelegation : bool;
}

(* 7701(a)(12)(B) *)
let delegate_of_guam_or_samoa (ctx : guam_samoa_context) : delegate =
  { authorized_officer_employee_or_agency = "other_department_or_agency_or_possession_officer_or_employee";
    authorized_directly_or_by_redelegation = ctx.authorized_by_secretary || ctx.by_redelegation }

let is_guam_or_samoa_chapter_context (ctx : guam_samoa_context) : bool =
  (ctx.territory = Guam || ctx.territory = American_Samoa) &&
  (ctx.chapter = Chapter_1 || ctx.chapter = Chapter_2 || ctx.chapter = Chapter_21)

let delegate_of_12 (ctx : guam_samoa_context) : delegate =
  if is_guam_or_samoa_chapter_context ctx then delegate_of_guam_or_samoa ctx
  else delegate_of ctx.official
